local function decode(keys, values)
 local list, result = {}, {}
 for value in (values.."|"):gmatch("(.-)|") do list[#list+1]=value end
 local i=0
 for key in keys:gmatch("%S+") do i=i+1;result[key]=list[i] end
 assert(i==#list, "AAC trading translation count mismatch")
 return result
end
